// Contract
export * from './lib/field-renderer-contract';

// The field-type vocabulary — the one list both apps read.
//
// It lives in the `/vocabulary` secondary entry point and is re-exported here for convenience, so
// code that already pulls the components in gets the type names without a second import. A consumer
// that wants *only* the vocabulary should import `velocity-core-renderer/vocabulary`
// directly: reaching it through this entry point drags the components along with it.
export * from 'velocity-core-renderer/vocabulary';

