import {
  collectExtras,
  FieldConfigExtras,
  readArray,
  readConfigSource,
  readNumber,
  readOption,
  readRecord,
  readString,
} from './config-readers';
import {
  ConfigSelectOption,
  ConfigSelectOptionGroup,
  FieldChoiceOption,
  parseChoiceOptions,
} from './field-definition-type-common.model';

/**
 * Every extension a `Media` field can accept, grouped as the dropdown heads them.
 *
 * A set rather than one at a time: the slot declares which extensions it takes, and "any of
 * these" is the normal answer. There is no `'all'` entry — "everything" is every extension
 * selected, which `p-multiselect`'s own toggle-all checkbox says in one click and which
 * {@link DEFAULT_MEDIA_FIELD_CONFIG} starts a new field on. A sentinel value would have to be
 * kept exclusive of every real one by hand, and would read as a 94th extension in a list of 93.
 *
 * Extensions are stored with their leading dot and upper-cased, exactly as supplied — `.TAR.GZ`
 * genuinely carries two dots and is not a typo. The source list had `JPG` and `XAPK` without the
 * leading dot alone among ninety-odd entries; both are written with one here so a stored value is
 * the same shape whichever extension it names.
 *
 * The single source of truth: {@link MEDIA_FILE_EXTENSIONS} and
 * {@link MEDIA_FILE_EXTENSION_OPTIONS} are both derived from it, so a list that grows cannot grow
 * in one place and not the other.
 */
const MEDIA_FILE_EXTENSION_GROUPS = [
  {
    label: 'Text Files',
    items: ['.DOC', '.DOCX', '.EML', '.MSG', '.ODT', '.PAGES', '.RTF', '.TEX', '.TXT', '.WPD'].map(
      toExtensionOption,
    ),
  },
  {
    label: 'Data Files',
    items: [
      '.AAE',
      '.BIN',
      '.CSV',
      '.DAT',
      '.KEY',
      '.LOG',
      '.MPP',
      '.OBB',
      '.PPT',
      '.PPTX',
      '.RPT',
      '.TAR',
      '.VCF',
      '.XML',
    ].map(toExtensionOption),
  },
  {
    label: 'Audio Files',
    items: ['.AIF', '.FLAC', '.M3U', '.M4A', '.MID', '.MP3', '.OGG', '.WAV', '.WMA'].map(
      toExtensionOption,
    ),
  },
  {
    label: 'Video Files',
    items: [
      '.3GP',
      '.ASF',
      '.AVI',
      '.FLV',
      '.M4V',
      '.MOV',
      '.MP4',
      '.MPG',
      '.SWF',
      '.TS',
      '.VOB',
      '.WMV',
    ].map(toExtensionOption),
  },
  {
    label: 'Raster Image Files',
    items: [
      '.BMP',
      '.DCM',
      '.DDS',
      '.DJVU',
      '.GIF',
      '.HEIC',
      '.JPG',
      '.PNG',
      '.PSD',
      '.TGA',
      '.TIF',
    ].map(toExtensionOption),
  },
  {
    label: 'Vector Image Files',
    items: ['.AI', '.CDR', '.EMF', '.EPS', '.PS', '.SKETCH', '.SVG', '.VSDX'].map(
      toExtensionOption,
    ),
  },
  {
    label: 'Page Layout Files',
    items: ['.INDD', '.OXPS', '.PDF', '.PMD', '.PUB', '.QXP', '.XPS'].map(toExtensionOption),
  },
  {
    label: 'Spreadsheet Files',
    items: ['.NUMBERS', '.ODS', '.XLR', '.XLS', '.XLSX'].map(toExtensionOption),
  },
  {
    label: 'CAD Files',
    items: ['.DGN', '.DWG', '.DXF', '.STEP', '.STL', '.STP'].map(toExtensionOption),
  },
  {
    label: 'Compressed Files',
    items: [
      '.7Z',
      '.CBR',
      '.DEB',
      '.GZ',
      '.PKG',
      '.RAR',
      '.RPM',
      '.TAR.GZ',
      '.XAPK',
      '.ZIP',
      '.ZIPX',
    ].map(toExtensionOption),
  },
];

/** An extension as one dropdown entry. Label and value are the same text: the extension is what
    an admin is choosing and what gets stored, and a prettier caption would only be the same
    string with the dot filed off. */
function toExtensionOption(extension: string): ConfigSelectOption<string> {
  return { label: extension, value: extension };
}

/**
 * Every offered extension, flattened and in menu order — what a saved value is validated against,
 * and what "all of them" means.
 *
 * The order matters beyond display: {@link parseFileExtensions} answers in it, so a stored
 * selection reads back grouped the way the menu presents it however it was written.
 */
export const MEDIA_FILE_EXTENSIONS: readonly string[] = MEDIA_FILE_EXTENSION_GROUPS.flatMap(
  (group) => group.items.map((item) => item.value),
);

/**
 * A `Media` field's extension.
 *
 * `string` rather than a union of ninety-odd literals, unlike every other option-typed config
 * member here. The list is data an admin will keep adding to — it already changed once — and a
 * literal union would turn each addition into a type that every `switch` and comparison has to be
 * rechecked against, for a guarantee {@link parseFileExtensions} already enforces at the only
 * point a value enters. See {@link MEDIA_FILE_EXTENSIONS}.
 */
export type MediaFileExtension = string;

/** The dropdown's own shape, grouped. Mutable arrays because `p-select`'s `options` input is. */
export const MEDIA_FILE_EXTENSION_OPTIONS: ConfigSelectOptionGroup<MediaFileExtension>[] =
  MEDIA_FILE_EXTENSION_GROUPS.map((group) => ({
    label: group.label,
    items: group.items.map(({ label, value }) => ({ label, value })),
  }));

/**
 * How large the placeholder is drawn.
 *
 * Deliberately **not** `FIELD_INPUT_SIZES` from `field-definition-type-common.model.ts`, which the
 * six other configs share. That one is `'' | 'small' | 'large'` because it is handed straight to a
 * PrimeNG control's `size` input, and its empty member means "whatever the theme's default is".
 * A `Media` field draws an icon rather than a PrimeNG control, so there is no control default to
 * defer to — every value here names a size, and the middle one is a real choice rather than an
 * absent one.
 */
export const MEDIA_PREVIEW_SIZES = ['small', 'medium', 'large'] as const;

export type MediaPreviewSize = (typeof MEDIA_PREVIEW_SIZES)[number];

export const MEDIA_PREVIEW_SIZE_OPTIONS: ConfigSelectOption<MediaPreviewSize>[] = [
  { label: 'Small', value: 'small' },
  { label: 'Medium', value: 'medium' },
  { label: 'Large', value: 'large' },
];

/**
 * What a `Media` field's `fieldConfig` JSON deserialises to.
 *
 * Read by `MediaFieldInputComponent`, written by `MediaFieldConfigComponent`.
 *
 * Every member here is a *declaration about the slot* rather than a display setting, which is what
 * separates this config from its neighbours: `MediaFieldInputComponent` draws a placeholder and
 * accepts no file, so nothing below is enforced by this app yet. They are recorded so the field
 * definition states its own contract, and so whatever eventually uploads against it has the answer
 * already saved.
 */
export interface MediaFieldConfig extends FieldConfigExtras {
  /**
   * The extensions this slot accepts.
   *
   * Always held in {@link MEDIA_FILE_EXTENSIONS} order, never in the order they were ticked, so
   * two fields accepting the same set store the same string. Every extension selected is how a
   * slot says "any file" — see {@link MEDIA_FILE_EXTENSION_GROUPS} for why there is no `'all'`
   * sentinel. Empty is rejected by the editor: a slot that accepts nothing is not a slot.
   */
  fileExtensions: MediaFileExtension[];
  /** The cap, in megabytes. Always a number — unlike `NumberFieldConfig.max` there is no "no
      limit" here, since an uncapped upload slot is not something a field should be able to
      declare by leaving a box empty. `MediaFieldConfigComponent` rejects zero and below. */
  maxFileSizeMb: number;
  previewSize: MediaPreviewSize;
  /**
   * The kinds of media this slot is for, authored as label/value pairs.
   *
   * Authored rather than picked from a fixed list, because what counts as a "type" here is the
   * account's own vocabulary — Hero Image, Floor Plan, Walkthrough — not something this app can
   * enumerate ahead of time. That is why the editor reuses `FieldOptionsEditorComponent` and the
   * validity rules `RadioFieldConfigComponent` and `SelectFieldConfigComponent` already apply to
   * their own choices: at least one entry, every entry with a stored value, no two sharing one.
   *
   * `value` is what gets stored and `label` only what is shown — see {@link FieldChoiceOption}.
   */
  fieldTypeOptions: FieldChoiceOption[];
}

export const DEFAULT_MEDIA_FIELD_CONFIG: MediaFieldConfig = {
  // Everything, so a new field accepts any file until someone narrows it — the permissive default
  // is the one that cannot silently reject a file an admin never thought to allow.
  fileExtensions: [...MEDIA_FILE_EXTENSIONS],
  maxFileSizeMb: 5,
  previewSize: 'medium',
  fieldTypeOptions: [],
  extra: {},
};

/** A saved media config, defaulting every member it cannot read. See `parseTextFieldConfig` for
    why `defaults` is a parameter. */
export function parseMediaFieldConfig(
  json: string | null,
  defaults: MediaFieldConfig,
): MediaFieldConfig {
  const source = readConfigSource(json);

  if (source === null) {
    return defaults;
  }

  return {
    fileExtensions: parseFileExtensions(source['fileExtensions'], defaults.fileExtensions),
    // Not range-checked here. A saved zero is a fact about data this app may not have written, and
    // defaulting it away would hide the bad config rather than surface it — the editor flags it,
    // with the offending number still in the box to be fixed.
    maxFileSizeMb: readNumber(source['maxFileSizeMb'], defaults.maxFileSizeMb),
    previewSize: readOption(source['previewSize'], MEDIA_PREVIEW_SIZES, defaults.previewSize),
    fieldTypeOptions: parseChoiceOptions(
      readArray(source['fieldTypeOptions']),
      defaults.fieldTypeOptions,
      readString,
      readRecord,
    ),
    extra: collectExtras(source, defaults),
  };
}

/**
 * The extensions a saved config names, dropping every entry the list no longer offers.
 *
 * Answers in {@link MEDIA_FILE_EXTENSIONS} order rather than the stored order, which also
 * collapses duplicates — the same move `checkboxFieldRenderer`'s group codec makes, and for the
 * same reason: the selection is a set, so its stored order carries no information and letting it
 * vary would make two identical configs serialise differently.
 *
 * An absent member means a config written before this one existed, and takes the caller's default
 * — every extension. An explicitly empty array is honoured as empty, not repaired: it is a
 * deliberate state the editor then reports as invalid, and quietly turning it back into "accepts
 * everything" would be this app deciding a field's contract on the admin's behalf.
 */
function parseFileExtensions(raw: unknown, fallback: MediaFileExtension[]): MediaFileExtension[] {
  const entries = readArray(raw);

  if (entries === null) {
    return [...fallback];
  }

  const stored = new Set(entries.filter((entry): entry is string => typeof entry === 'string'));

  return MEDIA_FILE_EXTENSIONS.filter((extension) => stored.has(extension));
}
